import json,re
from pathlib import Path
p=Path('/home/zby/.codex/sessions/2026/08/31/rollout-2026-08-31T15-38-11-01a0580a-b41f-71b3-8108-5481164fb82f.jsonl')
calls={};rows=[]
for n,line in enumerate(p.open(),1):
    o=json.loads(line);pl=o.get('payload',{});t=pl.get('type')
    if o.get('type')=='response_item' and t in ('custom_tool_call','function_call'):
        calls[pl.get('call_id')]=(pl.get('input') if t=='custom_tool_call' else pl.get('arguments')) or ''
    elif o.get('type')=='response_item' and t in ('custom_tool_call_output','function_call_output'):
        x=pl.get('output','');s=x if isinstance(x,str) else json.dumps(x,ensure_ascii=False)
        m=re.search(r'Warning: truncated output \(original token count: (\d+)\)',s)
        if m: rows.append((int(m.group(1)),len(s.encode()),n,pl.get('call_id')))
def desc(raw):
    raw=raw if isinstance(raw,str) else json.dumps(raw,ensure_ascii=False)
    m=re.search(r'["\']?cmd["\']?\s*:\s*("(?:\\.|[^"\\])*")',raw,re.S)
    if m:
        try:return ' '.join(json.loads(m.group(1)).split())[:180]
        except Exception:pass
    return ' '.join(raw.split())[:180]
for tok,b,n,cid in sorted(rows,reverse=True):
    print(f'{tok:6} orig_tokens {b:6} stored_bytes line {n:4} | {desc(calls.get(cid,""))}')
PY"]

